import Foundation

/// One lookup for every UI string written as (Italian, English) pairs, in all
/// 13 interface languages. Tables live in `UIStrings` (one file per language,
/// generated by scripts/l10n-extract.py + translation) and are keyed by the
/// English source text. Strings with interpolated values are matched against
/// templates where each `\(…)` became `{0}`, `{1}`…, so "3 items" finds the
/// "{0} items" entry and the translation can move the value around.
public enum UIText {
    /// Locale of the chosen interface language, for dates and numbers.
    public static var locale: Locale { Locale(identifier: AppLanguage.current.localeIdentifier) }

    public static func t(_ italian: String, _ english: String) -> String {
        let language = AppLanguage.current.resolved
        switch language {
        case .it: return italian
        case .en, .system: return english
        default: return translate(english, to: language) ?? english
        }
    }

    /// Translation of an English UI string, or nil when no table has it.
    /// Used by `L10n.tr` too, before it falls back to English.
    public static func translate(_ english: String, to language: AppLanguage) -> String? {
        guard let table = UIStrings.table(for: language), !table.isEmpty else { return nil }
        if let exact = table[english] { return exact }
        let key = CacheKey(language: language.rawValue, english: english)
        if let cached = cache.withLock({ $0[key] }) { return cached.value }
        let result = templateMatch(english, language: language, table: table)
        cache.withLock { store in
            if store.count > 4000 { store.removeAll(keepingCapacity: true) }
            store[key] = Cached(value: result)
        }
        return result
    }

    // MARK: Templates

    private struct CacheKey: Hashable { let language: String; let english: String }
    private struct Cached { let value: String? }
    private struct Template {
        let regex: NSRegularExpression
        let translation: String
        let literalLength: Int
    }

    private static let cache = Locked<[CacheKey: Cached]>([:])
    private static let templates = Locked<[String: [Template]]>([:])

    private static func templateMatch(_ english: String, language: AppLanguage, table: [String: String]) -> String? {
        let list = templates.withLock { store -> [Template] in
            if let built = store[language.rawValue] { return built }
            let built = buildTemplates(table)
            store[language.rawValue] = built
            return built
        }
        let range = NSRange(english.startIndex..., in: english)
        for template in list {
            guard let match = template.regex.firstMatch(in: english, range: range) else { continue }
            var out = template.translation
            for i in 0..<(match.numberOfRanges - 1) {
                guard let r = Range(match.range(at: i + 1), in: english) else { continue }
                out = out.replacingOccurrences(of: "{\(i)}", with: String(english[r]))
            }
            return out
        }
        return nil
    }

    /// Longest literal text first, so "{0} files selected" wins over "{0}".
    private static func buildTemplates(_ table: [String: String]) -> [Template] {
        var result: [Template] = []
        for (source, translation) in table where source.contains("{0}") {
            var pattern = "^"
            var literal = 0
            var rest = Substring(source)
            while let open = rest.range(of: "{") {
                let before = rest[..<open.lowerBound]
                if let close = rest[open.upperBound...].firstIndex(of: "}"),
                   Int(rest[open.upperBound..<close]) != nil {
                    pattern += NSRegularExpression.escapedPattern(for: String(before)) + "(.*?)"
                    literal += before.count
                    rest = rest[rest.index(after: close)...]
                } else {
                    pattern += NSRegularExpression.escapedPattern(for: String(rest[..<open.upperBound]))
                    literal += before.count + 1
                    rest = rest[open.upperBound...]
                }
            }
            pattern += NSRegularExpression.escapedPattern(for: String(rest)) + "$"
            literal += rest.count
            guard literal > 0, let regex = try? NSRegularExpression(pattern: pattern, options: [.dotMatchesLineSeparators]) else { continue }
            result.append(Template(regex: regex, translation: translation, literalLength: literal))
        }
        return result.sorted { $0.literalLength > $1.literalLength }
    }
}

/// Minimal lock box (Swift 6 friendly, macOS 14 deployment).
final class Locked<Value>: @unchecked Sendable {
    private var value: Value
    private let lock = NSLock()
    init(_ value: Value) { self.value = value }
    func withLock<R>(_ body: (inout Value) -> R) -> R {
        lock.lock(); defer { lock.unlock() }
        return body(&value)
    }
}

/// Per-language tables, keyed by English source text (templates use {0}, {1}…).
/// Each language lives in its own file: UIStrings+<code>.swift.
public enum UIStrings {
    static func table(for language: AppLanguage) -> [String: String]? {
        switch language {
        case .de: de
        case .es: es
        case .ptBR: ptBR
        case .ko: ko
        case .fr: fr
        case .it: it
        case .ja: ja
        case .ru: ru
        case .tr: tr
        case .fa: fa
        case .zhHans: zhHans
        case .zhHant: zhHant
        case .en, .system: nil
        }
    }
}
